package org.marketreview.nativeapp;
import android.content.*;import android.media.*;import android.widget.*;import android.view.*;import java.io.*;import java.nio.file.*;import java.util.*;import org.json.*;
final class ArchiveVideoHostChecks{
 static Object field(Object obj,String name)throws Exception{java.lang.reflect.Field x=obj.getClass().getDeclaredField(name);x.setAccessible(true);return x.get(obj);}
 interface Condition{boolean get()throws Exception;}
 static void await(FlowInstrumentation f,Condition test,String label)throws Exception{long until=android.os.SystemClock.elapsedRealtime()+15000;boolean[] ok={false};while(android.os.SystemClock.elapsedRealtime()<until){f.ui(()->{try{ok[0]=test.get();}catch(Exception e){throw new RuntimeException(e);}});if(ok[0]){f.check(true,label);return;}Thread.sleep(100);}throw new AssertionError(label+"; status="+((TextView)field(f.activity.archiveVideoScreen,"status")).getText());}
 static void run(FlowInstrumentation f)throws Exception{
  File root=new File(f.activity.getFilesDir(),"recognition-tests/media");root.mkdirs();File path=new File(root,"generated-video-"+UUID.randomUUID()+".mp4");try(InputStream in=f.getContext().getAssets().open("archive-video-test.mp4")){Files.copy(in,path.toPath());}
  byte[] bytes=Files.readAllBytes(path.toPath());StringBuilder sha=new StringBuilder();for(byte b:java.security.MessageDigest.getInstance("SHA-256").digest(bytes))sha.append(String.format(Locale.ROOT,"%02x",b&255));
  JSONObject row=new JSONObject().put("id","native-video-fixture").put("title","生成的解码定位测试，非平台作品").put("status","completed").put("pipelineState","complete").put("autoEnabled",false).put("assetPath",path.getPath()).put("text","校对文字不自动绑定时间").put("originalText","原始文本").put("archive",new JSONObject().put("assetPath",path.getPath()).put("bytes",bytes.length).put("sha256",sha.toString())).put("asrResult",new JSONObject().put("text","测试识别稿").put("segments",new JSONArray().put(new JSONObject().put("start",3).put("end",4).put("text","试定位3秒"))));
  final JSONObject[] saved={null};
  ArchiveVideoReviewChecks.run(f);
  f.ui(()->{try{saved[0]=f.activity.businessStore.save("collections",row);f.activity.openBusiness("collection");BusinessScreen page=(BusinessScreen)((Map<?,?>)EtfMonitorHostChecks.field(f.activity,"businessPages")).get("business:collection");page.extension.loadCollection(saved[0]);((Button)page.findViewWithTag("openArchiveVideo")).performClick();f.check(f.activity.archiveVideoScreen.isShown(),"real collection video entry");f.check(field(f.activity.archiveVideoScreen,"player")==null,"no autoplay or decoder on entry");}catch(Exception e){throw new RuntimeException(e);}});
  f.click("核验并打开归档");await(f,()->(boolean)field(f.activity.archiveVideoScreen,"ready"),"native MediaPlayer prepared");
  f.ui(()->{try{f.check(!((MediaPlayer)field(f.activity.archiveVideoScreen,"player")).isPlaying(),"prepared remains paused");}catch(Exception e){throw new RuntimeException(e);}});
  f.click("播放");await(f,()->((MediaPlayer)field(f.activity.archiveVideoScreen,"player")).getCurrentPosition()>300,"native decoded playback position advances");f.click("暂停");f.click("试定位 3–4 秒（对应关系未核验）");await(f,()->Math.abs(((MediaPlayer)field(f.activity.archiveVideoScreen,"player")).getCurrentPosition()-3000)<600,"native seek actually reaches target");await(f,()->((TextView)field(f.activity.archiveVideoScreen,"status")).getText().toString().startsWith("已试定位"),"native seek callback completes");
  f.ui(()->{try{View surface=(View)field(f.activity.archiveVideoScreen,"video");f.check(Math.abs(surface.getWidth()*9.0-surface.getHeight()*16.0)<20,"video retains source aspect ratio");}catch(Exception e){throw new RuntimeException(e);}});f.shot("android-v37-video");
  f.ui(()->{try{f.check(ArchiveVideoReviewModel.canonical(saved[0]).equals(ArchiveVideoReviewModel.canonical(f.activity.archiveVideoCurrent("native-video-fixture"))),"review no transcript writes");f.activity.goHome();f.check(field(f.activity.archiveVideoScreen,"player")==null,"leave releases player");f.activity.openArchiveVideo(saved[0]);f.check(field(f.activity.archiveVideoScreen,"player")==null,"reopen stays paused");}catch(Exception e){throw new RuntimeException(e);}});
  SourceHistoryChecks.recreateActivity(f);
  f.ui(()->{try{f.check(f.activity.archiveVideoScreen!=null&&f.activity.archiveVideoScreen.isShown(),"video reader restores");f.check(field(f.activity.archiveVideoScreen,"player")==null,"recreate never autoplays");JSONObject changed=new JSONObject(saved[0].toString()).put("text","externally changed");f.activity.businessStore.save("collections",changed);ArchiveVideoReviewChecks.button(f.activity.archiveVideoScreen,"核验并打开归档").performClick();f.check(field(f.activity.archiveVideoScreen,"player")==null,"changed version refuses decode");f.check(((TextView)field(f.activity.archiveVideoScreen,"status")).getText().toString().contains("版本"),"version conflict explicit");f.activity.onBackPressed();f.check(((String)EtfMonitorHostChecks.field(f.activity,"activePage")).isEmpty(),"video return home");}catch(Exception e){throw new RuntimeException(e);}});
  f.check(Arrays.equals(bytes,Files.readAllBytes(path.toPath())),"media bytes unchanged");
 }
}

